"""CPU map backend and the replay agent.

The agent owns the live control plane state of one job:

* resident images with their transition cells and reference counts,
* process identities (units) with their request marks and contexts,
* connections with their retained packets and delivery receipts,
* current file inodes with their pinned epoch and state.

Every operation is atomic.  A failed precondition leaves the state, including
the high water marks and the capacity counters, untouched and answers
``{"error": "rejected"}``.
"""
import binascii
import struct

try:  # the project is used both as a package and as a plain directory
    from .create_dfa import create
    from ..syntax import PolicyError
except ImportError:  # pragma: no cover - depends on the import style
    from ebpf.create_dfa import create
    from syntax import PolicyError

#: Target of a transition that can never be taken.
DENY = 4294967295

#: Tag of a modelled transport frame.
WIRE_MAGIC = b'EMC4'


class Reject(Exception):
    """A replay precondition failed; nothing changed."""


class MemoryMap(object):
    """Memory map of the transition cells of one image.

    A cell exists for every transition whose target is not ``DENY``; the
    acceptance flags and the ``DENY`` entries do not consume a cell.
    """

    __slots__ = ('cells',)

    def __init__(self):
        self.cells = {}

    def install(self, rows, labels):
        """Install the cells of *rows*; *labels* maps a column to its label."""
        self.cells = {}
        for state, row in enumerate(rows):
            for column, target in enumerate(row):
                if target != DENY:
                    self.cells[(state, labels[column])] = target

    def __len__(self):
        return len(self.cells)


class Image(object):
    """One resident, immutable image."""

    __slots__ = ('epoch', 'accept', 'rows', 'labels', 'map', 'refs')

    def __init__(self, epoch, accept, rows, labels):
        self.epoch = epoch
        self.accept = accept
        self.rows = rows
        self.labels = labels
        self.map = MemoryMap()
        self.map.install(rows, labels)
        self.refs = 0

    @property
    def cells(self):
        return len(self.map)

    def advance(self, state, column):
        """Advance a context by one service; DENY is sticky."""
        if state == DENY:
            return DENY
        return self.rows[state][column]


class Unit(object):
    """One live process identity."""

    __slots__ = ('key', 'service', 'mark', 'contexts')

    def __init__(self, key, service):
        self.key = key
        self.service = service
        self.mark = 0
        self.contexts = {}


class Packet(object):
    """One retained packet."""

    __slots__ = ('epoch', 'state', 'destination', 'label', 'wire')

    def __init__(self, epoch, state, destination, label, wire):
        self.epoch = epoch
        self.state = state
        self.destination = destination
        self.label = label
        self.wire = wire


class Connection(object):
    """One open connection generation."""

    __slots__ = ('ident', 'generation', 'packets', 'mark', 'receipts')

    def __init__(self, ident, generation):
        self.ident = ident
        self.generation = generation
        self.packets = {}
        self.mark = 0
        self.receipts = {}


class Inode(object):
    """One current file inode generation."""

    __slots__ = ('ident', 'generation', 'epoch', 'state')

    def __init__(self, ident, generation, epoch, state):
        self.ident = ident
        self.generation = generation
        self.epoch = epoch
        self.state = state


class Agent(object):
    """The replay agent of one job."""

    def __init__(self, services, limits):
        ordered = sorted(services, key=lambda service: service['label'])
        self.registry = list(services)
        self.columns = [service['name'] for service in ordered]
        self.column_of = dict((service['name'], index)
                              for index, service in enumerate(ordered))
        self.label_of = dict((service['name'], service['label'])
                             for service in ordered)
        self.labels = [service['label'] for service in ordered]
        self.limits = limits
        self.images = {}
        self.active = None
        self.epoch_mark = 0
        self.units = {}
        self.pairs = {}
        self.unit_mark = {}
        self.connections = {}
        self.connection_mark = {}
        self.files = {}
        self.file_mark = {}
        self.counts = {'units': 0, 'contexts': 0, 'connections': 0,
                       'packets': 0, 'files': 0}
        self.cells = 0

    # -- helpers ---------------------------------------------------------

    def _image(self, epoch):
        image = self.images.get(epoch)
        if image is None:
            raise Reject()
        return image

    def _unit(self, key):
        unit = self.units.get(key)
        if unit is None:
            raise Reject()
        return unit

    def _context(self, unit, rid):
        entry = unit.contexts.get(rid)
        if entry is None:
            raise Reject()
        return entry

    def _advance(self, image, state, service):
        return image.advance(state, self.column_of[service])

    # -- operations ------------------------------------------------------

    def op_stage(self, event):
        epoch = event['epoch']
        if epoch <= self.epoch_mark:
            raise Reject()
        try:
            image = create(event['policy'], self.registry)
        except PolicyError:
            raise Reject()
        accept = image['accept']
        rows = image['rows']
        if len(rows) > 8192:
            raise Reject()
        labels = self.labels
        cells = 0
        for row in rows:
            for target in row:
                if target != DENY:
                    cells += 1
        if len(self.images) + 1 > self.limits['images']:
            raise Reject()
        if self.cells + cells > self.limits['cells']:
            raise Reject()
        resident = Image(epoch, accept, rows, labels)
        self.images[epoch] = resident
        self.epoch_mark = epoch
        self.cells += cells
        return {'ok': True, 'epoch': epoch,
                'image': {'accept': list(accept), 'rows': [list(row) for row in rows]}}

    def op_commit(self, event):
        epoch = event['epoch']
        self._image(epoch)
        self.active = epoch
        return {'ok': True}

    def op_retire(self, event):
        epoch = event['epoch']
        image = self._image(epoch)
        if epoch == self.active:
            raise Reject()
        if image.refs:
            raise Reject()
        del self.images[epoch]
        self.cells -= image.cells
        return {'ok': True}

    def op_spawn(self, event):
        key = tuple(event['unit'])
        namespace, pid, generation = key
        service = event['service']
        if service not in self.label_of:
            raise Reject()
        if (namespace, pid) in self.pairs:
            raise Reject()
        if generation <= self.unit_mark.get((namespace, pid), 0):
            raise Reject()
        if self.counts['units'] + 1 > self.limits['units']:
            raise Reject()
        unit = Unit(key, service)
        self.units[key] = unit
        self.pairs[(namespace, pid)] = key
        self.unit_mark[(namespace, pid)] = generation
        self.counts['units'] += 1
        return {'ok': True}

    def op_clone(self, event):
        parent_key = tuple(event['parent'])
        child_key = tuple(event['child'])
        parent = self._unit(parent_key)
        namespace, pid, generation = child_key
        if (namespace, pid) in self.pairs:
            raise Reject()
        if generation <= self.unit_mark.get((namespace, pid), 0):
            raise Reject()
        if self.counts['units'] + 1 > self.limits['units']:
            raise Reject()
        if self.counts['contexts'] + len(parent.contexts) > self.limits['contexts']:
            raise Reject()
        child = Unit(child_key, parent.service)
        child.mark = parent.mark
        child.contexts = dict(parent.contexts)
        for epoch, _ in child.contexts.values():
            self._image(epoch).refs += 1
        self.units[child_key] = child
        self.pairs[(namespace, pid)] = child_key
        self.unit_mark[(namespace, pid)] = generation
        self.counts['units'] += 1
        self.counts['contexts'] += len(child.contexts)
        return {'ok': True}

    def op_exit(self, event):
        key = tuple(event['unit'])
        unit = self._unit(key)
        for epoch, _ in unit.contexts.values():
            self._image(epoch).refs -= 1
        self.counts['contexts'] -= len(unit.contexts)
        del self.units[key]
        del self.pairs[(key[0], key[1])]
        self.counts['units'] -= 1
        return {'ok': True}

    def op_begin(self, event):
        key = tuple(event['unit'])
        rid = event['rid']
        unit = self._unit(key)
        if self.active is None:
            raise Reject()
        if rid <= unit.mark:
            raise Reject()
        if self.counts['contexts'] + 1 > self.limits['contexts']:
            raise Reject()
        epoch = self.active
        image = self._image(epoch)
        state = self._advance(image, 0, unit.service)
        unit.contexts[rid] = (epoch, state)
        unit.mark = rid
        image.refs += 1
        self.counts['contexts'] += 1
        return {'ok': True, 'epoch': epoch, 'state': state}

    def op_finish(self, event):
        key = tuple(event['unit'])
        rid = event['rid']
        unit = self._unit(key)
        epoch, state = self._context(unit, rid)
        del unit.contexts[rid]
        image = self._image(epoch)
        image.refs -= 1
        self.counts['contexts'] -= 1
        allow = bool(image.accept[state]) if state != DENY else False
        return {'ok': True, 'allow': allow}

    def op_open(self, event):
        ident, generation = event['connection']
        if ident in self.connections:
            raise Reject()
        if generation <= self.connection_mark.get(ident, 0):
            raise Reject()
        if self.counts['connections'] + 1 > self.limits['connections']:
            raise Reject()
        self.connections[ident] = Connection(ident, generation)
        self.connection_mark[ident] = generation
        self.counts['connections'] += 1
        return {'ok': True}

    def op_close(self, event):
        ident, generation = event['connection']
        connection = self.connections.get(ident)
        if connection is None or connection.generation != generation:
            raise Reject()
        for packet in connection.packets.values():
            self._image(packet.epoch).refs -= 1
        self.counts['packets'] -= len(connection.packets)
        del self.connections[ident]
        self.counts['connections'] -= 1
        return {'ok': True}

    def op_send(self, event):
        key = tuple(event['unit'])
        rid = event['rid']
        ident, generation = event['connection']
        stream = event['stream']
        destination = event['destination']
        unit = self._unit(key)
        epoch, state = self._context(unit, rid)
        connection = self.connections.get(ident)
        if connection is None or connection.generation != generation:
            raise Reject()
        if stream <= connection.mark:
            raise Reject()
        if destination not in self.label_of:
            raise Reject()
        if self.counts['packets'] + 1 > self.limits['packets']:
            raise Reject()
        label = self.label_of[destination]
        wire = struct.pack('>4sIIIII', WIRE_MAGIC, epoch, state, label,
                           stream, generation)
        connection.packets[stream] = Packet(epoch, state, destination, label, wire)
        connection.mark = stream
        self._image(epoch).refs += 1
        self.counts['packets'] += 1
        return {'ok': True, 'wire': binascii.hexlify(wire).decode('ascii')}

    def op_recv(self, event):
        ident, generation = event['connection']
        stream = event['stream']
        key = tuple(event['unit'])
        rid = event['rid']
        wire = event['wire']
        connection = self.connections.get(ident)
        if connection is None or connection.generation != generation:
            raise Reject()
        packet = connection.packets.get(stream)
        if packet is None:
            raise Reject()
        unit = self._unit(key)
        if unit.service != packet.destination:
            raise Reject()
        if wire is not None:
            if len(wire) != 48:
                raise Reject()
            try:
                raw = binascii.unhexlify(wire)
            except (binascii.Error, ValueError):
                raise Reject()
            if raw != packet.wire:
                raise Reject()
        receipt = connection.receipts.get(stream)
        if receipt is not None:
            receipt_key, receipt_rid, epoch, state = receipt
            if receipt_key != key or receipt_rid != rid:
                raise Reject()
            if rid not in unit.contexts:
                raise Reject()
            return {'ok': True, 'epoch': epoch, 'state': state}
        if rid <= unit.mark:
            raise Reject()
        if self.counts['contexts'] + 1 > self.limits['contexts']:
            raise Reject()
        epoch = packet.epoch
        image = self._image(epoch)
        state = self._advance(image, packet.state, unit.service)
        unit.contexts[rid] = (epoch, state)
        unit.mark = rid
        image.refs += 1
        self.counts['contexts'] += 1
        connection.receipts[stream] = (key, rid, epoch, state)
        return {'ok': True, 'epoch': epoch, 'state': state}

    def op_store(self, event):
        key = tuple(event['unit'])
        rid = event['rid']
        ident, generation = event['file']
        unit = self._unit(key)
        epoch, state = self._context(unit, rid)
        inode = self.files.get(ident)
        if inode is None:
            if generation <= self.file_mark.get(ident, 0):
                raise Reject()
            if self.counts['files'] + 1 > self.limits['files']:
                raise Reject()
            self.files[ident] = Inode(ident, generation, epoch, state)
            self.file_mark[ident] = generation
            self._image(epoch).refs += 1
            self.counts['files'] += 1
        else:
            if inode.generation != generation:
                raise Reject()
            self._image(inode.epoch).refs -= 1
            inode.epoch = epoch
            inode.state = state
            self._image(epoch).refs += 1
        return {'ok': True}

    def op_load(self, event):
        ident, generation = event['file']
        key = tuple(event['unit'])
        rid = event['rid']
        inode = self.files.get(ident)
        if inode is None or inode.generation != generation:
            raise Reject()
        unit = self._unit(key)
        if rid <= unit.mark:
            raise Reject()
        if self.counts['contexts'] + 1 > self.limits['contexts']:
            raise Reject()
        image = self._image(inode.epoch)
        state = self._advance(image, inode.state, unit.service)
        unit.contexts[rid] = (inode.epoch, state)
        unit.mark = rid
        image.refs += 1
        self.counts['contexts'] += 1
        return {'ok': True, 'epoch': inode.epoch, 'state': state}

    def op_unlink(self, event):
        ident, generation = event['file']
        inode = self.files.get(ident)
        if inode is None or inode.generation != generation:
            raise Reject()
        del self.files[ident]
        self._image(inode.epoch).refs -= 1
        self.counts['files'] -= 1
        return {'ok': True}

    def op_inspect(self, event):
        images = [[epoch, len(image.rows), image.cells, image.refs]
                  for epoch, image in sorted(self.images.items())]
        return {'ok': True, 'active': self.active, 'images': images,
                'units': self.counts['units'],
                'contexts': self.counts['contexts'],
                'connections': self.counts['connections'],
                'packets': self.counts['packets'],
                'files': self.counts['files']}

    # -- dispatch --------------------------------------------------------

    def event(self, event):
        """Replay one event and return its outcome."""
        handler = getattr(self, 'op_' + event['op'], None)
        if handler is None:
            return {'error': 'rejected'}
        try:
            return handler(event)
        except Reject:
            return {'error': 'rejected'}
        except Exception:
            return {'error': 'rejected'}
